package fft

import "github.com/go-fft/fft/internal/kernels"

// fusedSEnabled is, per length, whether a Plan32 of that many points runs the
// one-kernel complex64 transform (kernels.FusedS<n>, generated by
// internal/genfused256): two fused passes with the twiddles between them folded
// into the first, eight complex64 per zmm (go-fft/fft#162). A variable so the
// tests can run both routes where they are on (plans record the choice when
// built).
var fusedSEnabled = map[int]bool{
	64: kernels.FusedS64On, 128: kernels.FusedS128On, 256: kernels.FusedS256On, 512: kernels.FusedS512On,
	1024: kernels.FusedS1024On, 2048: kernels.FusedS2048On, 4096: kernels.FusedS4096On,
	8192: kernels.FusedS8192On,
}

// fusedSRoute is the fused kernel length a Plan32 of n points takes: n, or 0.
func fusedSRoute(n int) int {
	if fusedSEnabled[n] {
		return n
	}
	return 0
}
